head.script:
scwin.onpageload = function() {
    scwin.doInit();
};
scwin.onpageunload = function() {};
scwin.createWindow = function() {
    var c_cnt = 8;
    var c_subName = "windowContainer_controlIconFormatter_WESD-435_(WSQ-4584)_sub";
    var c_xmlName = ".xml";
    for (var i = 0; i < c_cnt; i++) {
        windowContainer1.createWindow(c_subName + i, null, 'windowContainer_controlIconFormatter_WESD-435_(WSQ-4584)_sub0.xml', "", null, "existWindow", null, null);
    }
};
scwin.controlFormatter = function() {
    // 1. isCustom이 true인 버튼은 oncustomcontrolclick이벤트가 발생하여 엔진내부에서 정의한 동작이 수행되지 않습니다.
    // 2. 기본동작을 유지하기 위해서는 id와 className을 바꾸지 말아주세요.
    // 3. 기본동작이 구현된 컨트롤 버튼의 아이디는 아래와 같습니다.
    //    vertical, horizontal, cascade, sequential, closeAll, closeOthers, maximize, windowList
    // 4. isCustom을 true로 주실 경우, oncustomcontrolclick 이벤트가 발생합니다.
    return [{
            "id": "vertical",
            "className": "w2windowContainer_controlIcon_vertical",
            "isCustom": true
        }, {
            "id": "horizontal",
            "className": "w2windowContainer_controlIcon_horizontal",
            "isCustom": false
        }, {
            "id": "cascade",
            "className": "w2windowContainer_controlIcon_cascade",
            "isCustom": false
        }, {
            "id": "sequential",
            "className": "w2windowContainer_controlIcon_sequential",
            "isCustom": false
        }, {
            "id": "closeAll",
            "className": "w2windowContainer_controlIcon_closeAll",
            "isCustom": false
        }
        //			, {
        //				"id": "windowList",
        //				"className": "w2windowContainer_controlIcon_windowList",
        //				"isCustom" : false
        //			}
        //			, {
        //				"id": "test",
        //				"className": "showWindowsIcon",
        //				"isCustom" : true,
        //			}
    ];
};
scwin.doInit = function() {
    scwin.createWindow();
};
scwin.windowContainer1_oncustomcontrolclick = function(controlId) {
    alert("controlId : " + controlId);
};
scwin.unitTest = function() {
    //Unit tets
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#windowContainer1').width('500')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'windowContainer1_left') != null", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
